import ast, collections, time
from rsi6 import tasks, sandbox
fams = tasks.load("development")
print(len(fams), "families,", sum(len(f.instances) for f in fams), "instances")
def mined(instance):
    """Values that can be read off the verifier: its literals, its parameters, its closed sub-expressions."""
    tree = ast.parse(instance.source)
    env = dict(sandbox.NAMESPACE); env.update(instance.kwargs)
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.expr) and not isinstance(node, (ast.Name, ast.Starred)):
            try:
                code = compile(ast.Expression(node), "<m>", "eval")
            except Exception:
                continue
            status, value = sandbox.call(eval, code, dict(env), limit=0.2)
            if status == "ok" and sandbox.size_of(value) <= 5000 and not callable(value):
                out.append(value)
    out.extend(instance.kwargs.values())
    return out
def variants(v):
    yield v
    if isinstance(v, bool): return
    if isinstance(v, int):
        for d in (-1, 1): yield v + d
        yield -v; yield str(v); yield [v]; yield float(v)
    elif isinstance(v, float):
        yield int(v); yield -v
    elif isinstance(v, str):
        yield v[::-1]; yield [v]; yield v.split(); yield list(v); yield len(v)
        try: yield int(v)
        except Exception: pass
    elif isinstance(v, (list, tuple)):
        v = list(v); yield v; yield v[::-1]; yield len(v)
        try: yield sorted(v)
        except Exception: pass
        if v and all(isinstance(x, str) for x in v): yield "".join(v); yield " ".join(v)
        if v and all(isinstance(x, int) and not isinstance(x, bool) for x in v): yield sum(v)
solved = collections.Counter(); total = collections.Counter(); calls = 0; t0 = time.time()
solved_f = collections.defaultdict(list)
for f in fams:
    for inst in f.instances:
        total[f.module] += 1
        ver = sandbox.Verifier(inst)
        ok = False
        seen = set()
        for v in mined(inst) + [0, 1, 2, "", [], "a", 0.0, True]:
            for c in variants(v):
